// x: length-16 feature vector
// W: 4x16 projection matrix stored on device
function project(x, W){
  const y = new Array(4).fill(0);
  for(let i=0;i<4;i++){
    let s=0;
    for(let j=0;j<16;j++) s += W[i][j]*x[j];
    y[i] = s;
  }
  return y;
}
```

